---
name: solo-pleb-check
description: >-
  The solo pleb check script (python) that solo-pleb-setup writes verbatim to
  /workspace/solo-pleb/check.py on first run and on every update. Not used on
  its own.
---
The solo pleb check script. solo-pleb-setup writes the python block below to /workspace/solo-pleb/check.py on first run and on every update.

```python
import json, os, sys, time, subprocess, math, datetime
from zoneinfo import ZoneInfo
POOLS={'ckpool':('Solo CKPool','2%','full stats'),'braiins':('Braiins Solo','0.5%','full stats'),'sololuck':('SoloLuck','0%','full stats'),
 'publicpool':('Public Pool','0%','full stats if its stats port answers, otherwise block alerts plus miner stats'),
 'atlas':('AtlasPool','1.5%','full stats (best effort), otherwise block alerts plus miner stats'),
 'nerdminers':('NerdMiners pool',None,'full stats'),'ocean':('OCEAN',None,'full stats'),
 'gobrrr':('Go Brrr Pool','0%','full stats if its public API answers (v1.2.3+), otherwise block alerts plus miner stats')}
def detect(u,port=None):
 import re, ipaddress
 m=re.match(r'^(?:[a-z0-9+.-]+://)?([^/:\s]+)(?::(\d+))?',(u or '').strip().lower()); h=m.group(1) if m else ''
 port=int(port or (m.group(2) if m and m.group(2) else 0) or 0) or None
 k=('ckpool' if h=='ckpool.org' or h.endswith('.ckpool.org') else 'braiins' if h=='solo.stratum.braiins.com' else 'atlas' if h=='solo.atlaspool.io'
 else 'publicpool' if h=='public-pool.io' or h.endswith('.public-pool.io') else 'sololuck' if h.endswith('stratum.sololuck.io')
 else 'nerdminers' if h.endswith('nerdminers.org') else 'ocean' if h.endswith('ocean.xyz') else 'gobrrr' if h.endswith('gobrrr.me') else None)
 home=False
 if not k and h:
  try: ip=ipaddress.ip_address(h); home=ip.is_private or ip in ipaddress.ip_network('100.64.0.0/10')
  except ValueError: home=h.endswith(('.local','.lan','.home','.home.arpa','.internal','.ts.net','.onion')) or '.' not in h
 plat='Umbrel' if home and h.split('.')[0]=='umbrel' else None
 app={2018:'Public Pool',21420:'Go Brrr Pool',21422:'Go Brrr Pool'}.get(port) if plat else None
 q=[]
 if k=='publicpool' and port in(13333,14333): q.append(f"port {port} on Public Pool is PPLNS (shared rewards), not solo. its solo ports are 3333 and TLS 4333")
 if k=='publicpool' and port==4333: q.append('port 4333 is TLS')
 if k=='atlas' and port==3333: q.append("AtlasPool's port 3333 has a minimum difficulty of 2,000 (about 400 GH/s or more), so a small miner may not show on its dashboard")
 if k in('ckpool','atlas','sololuck') and port==4334: q.append('port 4334 is the high-difficulty port')
 if k=='sololuck' and port==3335: q.append('port 3335 is minimum difficulty 1, for CPU miners and NerdMiners')
 if k=='sololuck' and port==3334: q.append('port 3334 is TLS')
 if k=='braiins' and port==443: q.append('port 443 here is plain stratum, not TLS')
 nm=POOLS[k][0] if k else app
 return {'host':h,'port':port,'pool':k,'name':nm,'fee':POOLS[k][1] if k else None,'watch':POOLS[k][2] if k else None,
 'solo':not(k=='publicpool' and port in(13333,14333)),'home':home,'platform':plat,'notes':q,
 'say':f"mining to {h}{':'+str(port) if port else ''}"+(f" ({nm})" if nm else '')}
if (sys.argv[1:] or [''])[0]=='detect':
 print(json.dumps(detect(*sys.argv[2:4]))); sys.exit()
ARGS=[x for x in sys.argv[1:] if x!='--dry']; DRY='--dry' in sys.argv[1:]
MODE=(ARGS or ['watch'])[0]; WATCH=MODE=='watch'
VERSION=19
D=os.environ.get('SOLO_PLEB_DIR','/workspace/solo-pleb'); STP=f'{D}/state.json'; BAKP=STP+'.bak'
HEALTH=MODE in('watch','fees','daily','weekly') and not DRY; STEP='reading config.json'
HLBL={'watch':'miner checks','fees':'fee checks','daily':'daily one-liners','weekly':'weekly digest'}; HTHR={'weekly':1}
def why(ex):
 if isinstance(ex,FileNotFoundError) and str(getattr(ex,'filename','') or '').endswith('config.json'): return 'config.json is missing, so setup needs redoing'
 if isinstance(ex,json.JSONDecodeError) and STEP=='reading config.json': return f"config.json isn't valid json (line {ex.lineno}), so i can't read your settings"
 m=(str(ex).strip().splitlines() or [''])[0][:120]
 return f"failed while {STEP} · {type(ex).__name__}"+(f": {m}" if m else '')
def _hcfg():
 try: c=json.load(open(f'{D}/config.json')); return c if isinstance(c,dict) else {}
 except Exception: return {}
def _hstate():
 for p in (STP,BAKP):
  try:
   x=json.load(open(p))
   if isinstance(x,dict): return x
  except Exception: pass
 return {}
def _when(t,c):
 try: z=ZoneInfo(c.get('timezone') or 'UTC')
 except Exception: z=ZoneInfo('UTC')
 d=datetime.datetime.fromtimestamp(t,z); return d.strftime('%-d %b %H:%M ')+d.tzname()
def runlog(s,failed,now):
 if MODE!='watch' or DRY: return
 r=s.setdefault('runs',{}); day=lambda t: datetime.datetime.fromtimestamp(t,datetime.timezone.utc).strftime('%Y-%m-%d')
 v=r.setdefault(day(now),[0,0]); v[0]+=1; v[1]+=int(bool(failed))
 for k in [k for k in r if k<day(now-8*86400)]: r.pop(k)
def watcher_on(c,now): return bool((c.get('alerts') or {}).get('watcher',True)) and ((c.get('mutes') or {}).get('watcher') or 0)<now
def _fail(ex,tb):
 now=float(os.environ.get('SOLO_PLEB_NOW') or time.time()); w=why(ex)
 if not HEALTH: print(f"🟨 **check couldn't finish** · {w}"); return
 c=_hcfg(); s=_hstate(); h=s.setdefault('health',{}).setdefault(MODE,{})
 h['errs']=h.get('errs',0)+1; h.setdefault('first_err',now); h['last_err']=w; h['last_err_ts']=now; h['tb']=tb[-1500:]
 runlog(s,True,now)
 if h['errs']>=HTHR.get(MODE,3) and not h.get('warned') and watcher_on(c,now):
  h['warned']=True; n=h['errs']
  print('\n'.join([f"🟨 **watcher having trouble** · "+("the weekly digest couldn't be built" if MODE=='weekly' else f"the last {n} {HLBL[MODE]} failed"),
 f"{w} · since {_when(h['first_err'],c)}","your miners keep mining, only my checks are affected · i'll say when they work again"]))
 tmp=STP+'.tmp'
 with open(tmp,'w') as fh: json.dump(s,fh,indent=1); fh.flush(); os.fsync(fh.fileno())
 os.replace(tmp,STP)
def _crash(t,ex,tbo):
 import traceback
 try: _fail(ex,''.join(traceback.format_exception(t,ex,tbo)))
 except Exception as e2:
  if HEALTH and MODE=='watch': print(f"🟨 **watcher having trouble** · a check failed and i couldn't record it ({type(e2).__name__}: {str(e2)[:80]})")
 try: sys.stdout.flush()
 except Exception: pass
 os._exit(0)
sys.excepthook=_crash
C=json.load(open(f'{D}/config.json'))
if not isinstance(C,dict): raise ValueError('config.json is not a json object')
STEP='reading state.json'
def migrate():
 old=json.dumps(C,sort_keys=True); added=[]; ask=[]
 def add(path,val,note):
  o=C
  for k in path[:-1]: o=o.setdefault(k,{})
  if path[-1] not in o: o[path[-1]]=val; added.append({'key':'.'.join(path),'value':val,'note':note})
 if not C.get('pools') and C.get('addresses'): add(['pools'],[dict(a,role='primary') for a in C['addresses']],'pools list made from your addresses (the old list stays)')
 add(['alerts','watcher'],True,'one card if my checks keep failing, one when they work again')
 if any(a.get('role')=='backup' for a in C.get('pools') or []): add(['alerts','failover'],True,'moved to backup / back on primary cards')
 add(['mutes'],{},'room for muting an alert type for a few hours')
 if not C.get('timezone'): ask.append({'key':'timezone','question':'which city or timezone are you in?'})
 if not C.get('currency'): ask.append({'key':'currency','question':'which currency?'})
 fv=C.get('config_version'); C['config_version']=VERSION
 ch=json.dumps(C,sort_keys=True)!=old; wr=ch and not DRY
 if wr:
  p=f'{D}/config.json'; tmp=p+'.tmp'
  with open(tmp,'w') as fh: json.dump(C,fh,indent=1); fh.flush(); os.fsync(fh.fileno())
  os.replace(tmp,p)
 print(json.dumps({'from':fv,'to':VERSION,'added':added,'ask':ask,'written':wr}))
if MODE=='migrate': migrate(); sys.exit()
FAKE=os.environ.get('SOLO_PLEB_FAKE'); FH=None
if FAKE:
 import runpy; FH=runpy.run_path(FAKE)['handler']
TOR_START='/home/box/tor/start.sh'
def tor_up():
 import socket
 try: socket.create_connection(('127.0.0.1',9050),2).close(); return True
 except Exception: return False
def tor_start():
 if os.path.exists(TOR_START):
  try: subprocess.run(['/bin/bash',TOR_START],capture_output=True,timeout=60)
  except Exception: pass
  time.sleep(30)
if not FAKE and MODE!='sample' and C.get('route')=='tor' and not tor_up(): tor_start()
NOW=float(os.environ.get('SOLO_PLEB_NOW') or time.time())
SNOTE=[]
def load_state():
 for p in (STP,BAKP):
  if not os.path.exists(p): continue
  try:
   s=json.load(open(p))
   if not isinstance(s,dict): raise ValueError('not a dict')
   if p==BAKP and SNOTE: SNOTE.append('restored')
   return s
  except Exception:
   SNOTE.append('corrupt' if p==STP else 'bak_bad')
 return {}
S=load_state()
if 'corrupt' in SNOTE and WATCH and not DRY:
 try: os.replace(STP,f'{STP}.corrupt-{int(NOW)}')
 except Exception: pass
def save():
 if MODE=='status' or DRY: return
 tmp=STP+'.tmp'
 with open(tmp,'w') as fh: json.dump(S,fh,indent=1); fh.flush(); os.fsync(fh.fileno())
 if os.path.exists(STP):
  try:
   json.load(open(STP)); import shutil; shutil.copyfile(STP,BAKP+'.tmp'); os.replace(BAKP+'.tmp',BAKP)
  except Exception: pass
 os.replace(tmp,STP)
OUT=[]; LATER=[]; FOUND=[]
NEWSINCE='since' not in S; S.setdefault('since',NOW); S.setdefault('blocks',[])
try: TZ=ZoneInfo(C.get('timezone') or 'UTC')
except Exception: TZ=ZoneInfo('UTC')
AL=C.get('alerts',{}); DEF_OFF={'fees'}
if 'milestone' in AL:
 for k in('milestone_g','milestone_t'): AL.setdefault(k,AL['milestone'])
def on(k):
 m=C.get('mutes',{}).get(k) or 0
 return AL.get(k, k not in DEF_OFF) and m<NOW
def say(k,*lines):
 if MODE!='status' and on(k): OUT.append('\n'.join(x for x in lines if x))
def curl(url,ex,t):
 if FH:
  res=FH(url,ex); rc,body=res[0],res[1]
  if rc==0 and '-w' in ex: body=f'{body}\n{res[2] if len(res)>2 else 200}'
  return subprocess.CompletedProcess([url],rc,body or '','')
 cmd=['curl','-sk','-m',str(t)]+ex
 if '.onion' in url:
  if not tor_up(): tor_start()
  cmd+=['--proxy','socks5h://127.0.0.1:9050']
 r=subprocess.run(cmd+[url],capture_output=True,text=True)
 if '.onion' in url:
  for w in (20,40,60):
   if r.returncode in (0,22): break
   time.sleep(w); r=subprocess.run(cmd+[url],capture_output=True,text=True)
 return r
def get(url,data=None,auth=None,t=60):
 ex=['-f']+(['-u',auth] if auth else [])+(['-H','content-type: text/plain','--data-binary',data] if data else [])
 r=curl(url,ex,t)
 if r.returncode or not r.stdout.strip(): raise RuntimeError(f'fetch {r.returncode}')
 return r.stdout
def getc(url,t=60):
 r=curl(url,['-w','\n%{http_code}'],t)
 if r.returncode: raise RuntimeError(f'fetch {r.returncode}')
 b,_,c=r.stdout.rpartition('\n'); return int(c or 0),b
class Busy(Exception): pass
class NoStats(Exception): pass
def js(u): return json.loads(get(u))
N=C.get('node') or {}
RPC_OK={'getblockchaininfo','getblockcount','getbestblockhash','getblockhash','getblock','getblockheader'}
def rpc(m,p=[]):
 if m not in RPC_OK: raise RuntimeError(f'rpc method {m} not allowed')
 sec=os.environ.get(N.get('rpc_secret_env') or 'SOLO_PLEB_RPC',''); a=f"{N['rpc_user']}:{sec}" if N.get('rpc_user') else (sec or None)
 r=json.loads(get(N['rpc_url'],json.dumps({'jsonrpc':'1.0','id':'sp','method':m,'params':p}),a))
 if r.get('error'): raise RuntimeError(r['error'])
 return r['result']
MP=C.get('mempool_url') or ('https://mempool.space' if C.get('public_fallback') else None)
def mp(path): return js(f'{MP}/api{path}')
def f(x):
 x=float(x or 0)
 for u,s in ((1e18,'E'),(1e15,'P'),(1e12,'T'),(1e9,'G'),(1e6,'M'),(1e3,'k')):
  if x>=u: v=x/u; break
 else: v,s=x,''
 return (f'{v:.0f}' if v>=100 else f'{v:.1f}' if v>=10 else f'{v:.2f}')+(' '+s if s else '')
def fd(x): return f(x) if x<1e12 else f'{x/1e12:.2f} T'
def hs(x): return f(x)+('H/s' if f(x)[-1].isalpha() else ' H/s')
def pc(x):
 if not diff or not x: return None
 p=x/diff*100
 return f'{p:.2f}%' if p>=1 else f'{p:.{max(0,-math.floor(math.log10(p)))}f}%'
def tm(ts=None):
 d=datetime.datetime.fromtimestamp(ts or NOW,TZ); n=datetime.datetime.fromtimestamp(NOW,TZ)
 return d.strftime('%H:%M ' if d.date()==n.date() else '%-d %b %H:%M ')+d.tzname()
def dur(s):
 m=max(s,0)/60
 return f'{m:.0f} min' if m<120 else f'{m/60:.1f} h' if m<2880 else f'{m/1440:.1f} days'
def ordn(k): return f"{k}{'th' if 10<=k%100<=20 else {1:'st',2:'nd',3:'rd'}.get(k%10,'th')}"
def num(v):
 if isinstance(v,(int,float)): return float(v)
 v=str(v).strip(); m={'K':1e3,'M':1e6,'G':1e9,'T':1e12,'P':1e15,'E':1e18}
 return float(v[:-1])*m[v[-1].upper()] if v and v[-1].upper() in m else float(v or 0)
def iso(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()
def ts(v):
 if v in(None,''): return 0.0
 try: v=float(v); return v/1000 if v>1e11 else v
 except (TypeError,ValueError): return iso(str(v))
def subsidy(h): return 50/2**(h//210000)
SOLO_SLUGS={'solock','publicpool','braiinssolo','solopoolcom','futurebitapollosolo','ckpool','solo-ck','public-pool','braiins-solo','solopool'}
def is_solo(pl):
 nm=(pl or {}).get('name','') or ''; sl=(pl or {}).get('slug','') or ''
 return sl in SOLO_SLUGS or 'solo' in nm.lower() or 'public pool' in nm.lower()
PX={}
def price():
 cu=(C.get('currency') or '').upper()
 if not cu or not MP: return None
 if cu not in PX:
  try: PX[cu]=float(mp('/v1/prices')[cu])
  except Exception: PX[cu]=None
 return PX[cu]
SYM={'USD':'$','GBP':'£','EUR':'€','JPY':'¥','CAD':'C$','AUD':'A$'}
def money(v):
 cu=(C.get('currency') or '').upper(); sy=SYM.get(cu)
 if cu=='JPY': return f"¥{v:,.0f}"
 if sy: return f"{sy}{v:,.2f}" if v<100 else f"{sy}{v:,.0f}"
 return f"{v:,.2f} {cu}" if v<100 else f"{v:,.0f} {cu}"
def fx(btc):
 p=price(); return f" ≈ {money(btc*p)}" if p else ''
def sample():
 pl=C.get('pools') or [dict(a,role='primary') for a in C.get('addresses',[])]; bk=[a for a in pl if a.get('role')=='backup']
 ws=[m.get('worker') for m in C.get('miners',[]) if m.get('worker')]
 for ps in (S.get('pools') or {}).values(): ws+=[n for n in (ps.get('workers') or {}) if n not in ws]
 n=ws[0] if ws else 'your miner'
 hr=next((m.get('hashrate_ths',0)*1e12 for m in C.get('miners',[]) if m.get('worker')==n and m.get('hashrate_ths')),None)
 hr=hr or next((ps['workers'][n].get('hr') for ps in (S.get('pools') or {}).values() if (ps.get('workers') or {}).get(n,{}).get('hr')),None)
 lab='_sample, not a real alert_'; q=NOW-2100; R=['**solo pleb · sample alerts** · a test, nothing is wrong. real ones look like this, without the sample line']
 rb=[a for a in bk if a.get('stats') is not False]; bn=(bk[0].get('name') or bk[0]['pool']) if bk else None
 R.append('\n'.join(x for x in (lab,f"🟥 **{n} down** · not seen for {dur(NOW-q)}",' · '.join(x for x in (f"last seen {tm(q)}",f"was {hs(hr)}" if hr else None,'silent on primary and backup' if rb else None) if x)) if x))
 if rb: R.append('\n'.join((lab,f"🟨 **{n} moved to backup · {rb[0].get('name') or rb[0]['pool']}**"+(f" · {hs(hr)}" if hr else ''),f"primary quiet {dur(NOW-q)} · not down: still hashing, so odds and uptime keep counting · i'll say when it is back on primary")))
 elif bk: R.append('\n'.join((lab,f"🟨 **{n} not seen on primary** · may have failed over to your backup, {bn}, which i can't read",f"last seen on primary {tm(q)}"+(f" · was {hs(hr)}" if hr else '')+" · i'll say when it is back on primary")))
 off=[x for x in (('worker_quiet','down cards'),('failover','backup cards')) if not on(x[0]) and (x[0]!='failover' or bk)]
 if off: R.append(f"{' and '.join(x[1] for x in off)} are off in your settings right now, so you wouldn't get {'these' if len(off)>1 else 'that one'} · say if you want {'them' if len(off)>1 else 'it'} on")
 print('\n\n'.join(R))
if MODE=='sample': sample(); sys.exit()
if S.get('schema',1)<2 and not NEWSINCE:
 S['samples']=[[t,None if v==0 else v] for t,v in S.get('samples',[])]
 if S.pop('block_flagged',None): S['flag_best']=S.get('best_ever',0)
 for k,ps in S.get('pools',{}).items():
  for n,st in ps.get('workers',{}).items():
   up=st.get('up',[]); st.setdefault('drops',[u[0] for i,u in enumerate(up) if i and up[i-1][1]==1 and u[1]==0])
 if 'solo_tip' in S: S['solo_floor']=S['solo_tip']
 S['migrated']=NOW
S['schema']=2
STEP='reading your node and the network'
diff=tip=None; MPTIP=None
if N.get('rpc_url'):
 try:
  bi=rpc('getblockchaininfo'); tip=bi['blocks']; diff=bi['difficulty']; lag=bi['headers']-bi['blocks']
  if S.pop('node_down',None): say('node_lag',f"🟩 **node back** · rpc answering · at {tip:,}",f"down {dur(NOW-S.pop('node_down_ts',NOW))} · {tm()}")
  S['node_fails']=0
  if lag>=3 and not S.get('lagging'): say('node_lag',f"🟥 **node lagging** · {lag} blocks behind",f"at {bi['blocks']:,} of {bi['headers']:,} headers · {tm()}"); S['lagging']=True
  elif lag<3 and S.get('lagging'): say('node_lag',f"🟩 **node caught up** · at {tip:,}",tm()); S['lagging']=False
 except Exception:
  S['node_fails']=S.get('node_fails',0)+1
  if S['node_fails']>=2 and not S.get('node_down'):
   say('node_lag',"🟥 **node unreachable** · rpc not answering (2 checks in a row)",f"i'll say when it's back · {tm()}"); S['node_down']=True; S['node_down_ts']=NOW
if MP:
 try: MPTIP=int(get(f'{MP}/api/blocks/tip/height'))
 except Exception: pass
 if tip is None and MPTIP:
  tip=MPTIP
  try: diff=mp('/v1/mining/hashrate/3d')['currentDifficulty']
  except Exception: pass
diff=diff or S.get('difficulty'); S['difficulty']=diff
RPCUP=bool(N.get('rpc_url') and not S.get('node_down') and S.get('node_fails',0)==0)
def bhash(h): return rpc('getblockhash',[h]) if RPCUP else get(f'{MP}/api/block-height/{h}').strip()
def coinbase(h):
 if RPCUP:
  b=rpc('getblock',[rpc('getblockhash',[h]),2]); pay={}
  for v in b['tx'][0]['vout']:
   ad=v['scriptPubKey'].get('address'); pay[ad]=pay.get(ad,0)+v['value']
  return b['hash'],pay,b.get('time'),sum(pay.values())
 bh=get(f'{MP}/api/block-height/{h}').strip(); tx=mp(f"/tx/{get(f'{MP}/api/block/{bh}/txid/0').strip()}"); pay={}
 for v in tx['vout']:
  ad=v.get('scriptpubkey_address'); pay[ad]=pay.get(ad,0)+v['value']/1e8
 return bh,pay,(tx.get('status') or {}).get('block_time'),sum(pay.values())
CKB={'ckpool':'https://raw.stats.ckpool.org','braiins':'https://solo.braiins.com','sololuck':'https://sololuck.io','nerdminers':'https://pool.nerdminers.org'}
ATLAS='https://w9hv08n3kh.execute-api.us-east-1.amazonaws.com/prod'
def ckj(u):
 for i in(0,1):
  c,b=getc(u)
  if c!=429: break
  if i==0: time.sleep(1.5)
 if c==429: raise Busy()
 if c==404: return {}
 if c!=200 or not b.strip(): raise RuntimeError(f'http {c}')
 return json.loads(b)
TSNC_OK=('/api/public/v1/pool','/api/public/v1/stats/','/api/client/','/api/info')
def http_done(raw):
 head,sep,body=raw.partition(b'\r\n\r\n')
 if not sep: return False
 hd=head.decode('latin1').lower()
 if 'transfer-encoding: chunked' in hd: return body.endswith(b'0\r\n\r\n')
 for l in hd.split('\r\n'):
  if l.startswith('content-length:'): return len(body)>=int(l.split(':',1)[1].strip() or 0)
 return False
def http_parse(raw):
 head,_,body=raw.partition(b'\r\n\r\n')
 if not head.startswith(b'HTTP/'): raise RuntimeError('no http answer')
 code=int(head.split(b' ')[1]); hd=head.decode('latin1').lower()
 if 'transfer-encoding: chunked' in hd:
  out=b''
  while body:
   ln,_,rest=body.partition(b'\r\n')
   try: n=int(ln.split(b';')[0].strip() or b'0',16)
   except ValueError: break
   if n==0: break
   out+=rest[:n]; body=rest[n+2:]
  body=out
 return code,body.decode('utf8','replace')
def tsnc(a,path,t=30):
 if not path.startswith(TSNC_OK): raise RuntimeError('path not allowed on the tailscale link')
 if link_quiet(a): raise RuntimeError('shared link quiet window')
